commands.output:
table inet ab_dependency_guard {
	chain output {
		type filter hook output priority filter - 10; policy drop;
		oifname "lo" accept
		oifname "docker0" accept
		oifname "br-*" accept
		ct state established,related accept
		oifname "abegress0" ip daddr 10.0.2.2 tcp dport 8877 counter packets 0 bytes 0 accept
		counter packets 0 bytes 0 reject with icmpx admin-prohibited
	}

	chain forward {
		type filter hook forward priority filter - 10; policy accept;
		oifname "abegress0" ip daddr 10.0.2.2 tcp dport 8877 counter packets 0 bytes 0 accept
		oifname "abegress0" counter packets 0 bytes 0 reject with icmpx admin-prohibited
	}

	chain input {
		type filter hook input priority filter - 10; policy drop;
		iifname "lo" accept
		iifname "docker0" accept
		iifname "br-*" accept
		ct state established,related accept
		counter packets 0 bytes 0 reject with icmpx admin-prohibited
	}
}

